private static double EstimateTextWidth(string? text, double fontSize)
{
    if (string.IsNullOrEmpty(text))
        return 0;

    return text
        .Replace("\r", string.Empty, StringComparison.Ordinal)
        .Split('\n')
        .Max(line => line.Length) * fontSize * AvgGlyphAdvanceEm;
}

