it("close() during reconnect fires onDisconnect(null)", async () => {
  let disconnectErr: Error | null | undefined;
  let disconnectResolve: () => void = () => {};
  const disconnected = new Promise<void>((r) => {
    disconnectResolve = r;
  });
  const clock = new FakeClock();

  const t1 = new MockTransport();
  // Reconnect will never succeed — we close() before it gets a chance.
  const dialer = new MockDialer([
    t1,
    new Error("dial fail 1"),
    new Error("dial fail 2"),
    new Error("dial fail 3"),
    new Error("dial fail 4"),
    new Error("dial fail 5"),
    new Error("dial fail 6"),
    new Error("dial fail 7"),
    new Error("dial fail 8"),
    new Error("dial fail 9"),
    new Error("dial fail 10"),
  ]);

  testClient = await connect("ws://mock/ws", {
    onDisconnect(err) {
      disconnectErr = err;
      disconnectResolve();
    },
    onTransportDrop() {
      // Close while the reconnect loop is active.
      queueMicrotask(() => {
        testClient?.close();
      });
    },
    autoReconnect: { maxRetries: 10, baseDelay: 100, maxDelay: 500 },
    _dialer: dialer.dial,
    _clock: clock,
  });

  // Trigger transport drop.
  // The queueMicrotask inside onTransportDrop calls close() before any
  // backoff timer fires, aborting the reconnect loop immediately.
  t1.injectClose(1006, "");

  await disconnected;

  // User-initiated close during reconnect -> onDisconnect(null).
  expect(disconnectErr).toBeNull();
});

private function handleRouteException(\Throwable $e, array $route, Request $request): Response
{
    $logger = $this->container->has(\Semitexa\Core\Log\LoggerInterface::class)
        ? $this->container->get(\Semitexa\Core\Log\LoggerInterface::class)
        : null;

    if ($e instanceof \Semitexa\Core\Exception\NotFoundException) {
        if ($logger instanceof \Semitexa\Core\Log\LoggerInterface) {
            $logger->debug('Route not found', ['path' => $request->getPath(), 'message' => $e->getMessage()]);
        }

        $currentRouteName = $route['name'] ?? null;
        if ($currentRouteName !== self::ROUTE_NAME_404) {
            $route404 = \Semitexa\Core\Discovery\AttributeDiscovery::findRouteByName(self::ROUTE_NAME_404);
            if ($route404 !== null) {
                return $this->handleRoute($route404, $request);
            }
        }
        return Response::notFound($e->getMessage() ?: 'The requested resource was not found');
    }

    if ($logger instanceof \Semitexa\Core\Log\LoggerInterface) {
        $logger->error($e->getMessage(), [
            'exception' => get_debug_type($e),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $this->environment->appDebug ? $e->getTraceAsString() : 'hidden',
        ]);
    } else {
        // Fallback for critical errors when logger fails
        error_log("[Semitexa] Critical Error: " . $e->getMessage() . " in " . $e->getFile() . ":" . $e->getLine());
    }

    return \Semitexa\Core\Http\ErrorRenderer::render($e, $request, $this->environment->appDebug);
}

