func normalizeResult(result any) (ToolResult, error) {
	if result == nil {
		return ToolResult{
			TextResultForLLM: "",
			ResultType:       "success",
		}, nil
	}

	// ToolResult passes through directly
	if tr, ok := result.(ToolResult); ok {
		return tr, nil
	}

	// Strings pass through directly
	if str, ok := result.(string); ok {
		return ToolResult{
			TextResultForLLM: str,
			ResultType:       "success",
		}, nil
	}

	// MCP CallToolResult shape: { content: [...], isError?: bool }
	if tr, ok := convertCallToolResult(result); ok {
		return tr, nil
	}

	// Everything else gets JSON-serialized
	jsonBytes, err := json.Marshal(result)
	if err != nil {
		return ToolResult{}, fmt.Errorf("failed to serialize result: %w", err)
	}

	return ToolResult{
		TextResultForLLM: string(jsonBytes),
		ResultType:       "success",
	}, nil
}

pub fn explore<F: Renderable + 'static>(
    file_prefix: FilePrefix,
    image_specification: ImageSpecification,
    renderer: F,
) -> Result<(), Error> {
    // Keep backend selection under user control and let winit auto-detect by default.
    if running_in_wsl() && env::var_os("WINIT_UNIX_BACKEND").is_none() {
        eprintln!(
            "Note: WSL detected; using winit auto backend selection. Set WINIT_UNIX_BACKEND=wayland or x11 to force a backend."
        );
    }

    // Create the event loop with a friendlier failure path.
    let event_loop = std::panic::catch_unwind(EventLoop::new)
        .unwrap_or_else(|p| {
            let msg = panic_message(p);
            eprintln!("\nERROR: Failed to initialize windowing backend.\n{msg}\n");

            if running_in_wsl() {
                eprintln!("WSL detected.");
                eprintln!("If you're forcing X11, you may be missing X11 runtime libs.");
                eprintln!("On Ubuntu, try: sudo apt install -y libxcursor1");
                eprintln!("(and ensure DISPLAY is set; WSLg usually sets it automatically.)");
            } else {
                eprintln!("Tip: ensure your system has either a working Wayland compositor or X11 libraries installed.");
            }

            std::process::exit(1);
        });

    let mut raw_input = RawInputState::default();
    let stopwatch = Stopwatch::new("Fractal Explorer".to_string());

    // Read the parameters file here and convert it into a `RenderWindow`.
    let time = stopwatch.total_elapsed_seconds();
    let mut render_window = PixelGrid::new(
        stopwatch.total_elapsed_seconds(),
        file_prefix,
        ViewControl::new(time, image_specification),
        renderer,
    );

    let window = {
        let logical_size = LogicalSize::new(
            render_window.image_specification().resolution[0] as f64,
            render_window.image_specification().resolution[1] as f64,
        );
        WindowBuilder::new()
            .with_title("Fractal Explorer")
            .with_inner_size(logical_size)
            .with_min_inner_size(logical_size)
            .build(&event_loop)
            .unwrap()
    };

    let mut pixels = {
        let window_size = window.inner_size();
        let surface_texture = SurfaceTexture::new(window_size.width, window_size.height, &window);
        Pixels::new(
            render_window.image_specification().resolution[0],
            render_window.image_specification().resolution[1],
            surface_texture,
        )?
    };

    // GUI application main loop:
    event_loop.run(move |event, _, control_flow| {
        // Initialize once at startup; do not set a per-event default here.
        // `MainEventsCleared` is the sole owner of `WaitUntil(...)` scheduling.
        if let Event::NewEvents(StartCause::Init) = event {
            *control_flow = ControlFlow::Wait;
        }

        if let Event::WindowEvent { event, .. } = &event {
            raw_input.observe_window_event(event);

            match event {
                WindowEvent::CloseRequested => {
                    *control_flow = ControlFlow::Exit;
                    return;
                }
                WindowEvent::Resized(size)
                    if pixels.resize_surface(size.width, size.height).is_err() =>
                {
                    println!("ERROR:  unable to resize surface. Aborting.");
                    *control_flow = ControlFlow::Exit;
                    return;
                }
                _ => {}
            }
        }

        // Handle redraw requests from the windowing system.
        if let Event::RedrawRequested(_) = event {
            render_window.draw(pixels.frame_mut());
            if pixels.render().is_err() {
                println!("ERROR:  unable to render pixels. Aborting.");
                *control_flow = ControlFlow::Exit;
                return;
            }
        }

        if let Event::MainEventsCleared = event {
            // Close events
            if raw_input.key_held(VirtualKeyCode::Escape) {
                *control_flow = ControlFlow::Exit;
                return;
            }

            let center_command = view_center_command_from_user_input(
                &raw_input,
                &pixels,
                render_window.image_specification(),
            );

            let zoom_command = zoom_velocity_command_from_key_press(&raw_input);

            // Check for reset requests
            if reset_command_from_key_press(&raw_input) {
                render_window.reset();
            }

            // Now do the hard rendering math:
            let redraw_required = render_window.update(
                stopwatch.total_elapsed_seconds(),
                center_command,
                zoom_command,
            );

            if redraw_required {
                window.request_redraw();
            }

            if raw_input.key_pressed_this_frame(VirtualKeyCode::Space) {
                render_window.render_to_file();
            }

            raw_input.end_frame();

            let should_tick = raw_input.has_active_keys()
                || render_window.render_task_is_busy()
                || render_window.redraw_required()
                || render_window.adaptive_rendering_required();
            *control_flow = if should_tick {
                ControlFlow::WaitUntil(Instant::now() + Duration::from_millis(ACTIVE_LOOP_TICK_MS))
            } else {
                ControlFlow::Wait
            };
        }
    });
}

def _validate_hooks(self, hooks: Sequence[HookP] | None) -> tuple[HookP, ...]:
    """Validate that all hooks are of the expected type and return as tuple."""
    if not hooks:
        return ()
    for hook in hooks:
        if not isinstance(hook, self._ALLOWED_HOOK_TYPES):
            expected = ", ".join(t.__name__ for t in self._ALLOWED_HOOK_TYPES)
            raise TypeError(
                f"Invalid hook type: {type(hook).__name__}. Expected: {expected}"
            )
    return tuple(hooks)

private static void AppendNodeLabel(
    StringBuilder sb,
    Label label,
    Theme theme,
    double centerX,
    double centerY,
    double fontSize,
    string textColor)
{
    var lines = GetRenderedLabelLines(label);
    double lineHeight = fontSize * DefaultLabelLineHeight;
    double firstBaselineY = centerY + fontSize * 0.35 - ((lines.Length - 1) * lineHeight / 2);

    if (lines.Length == 1)
    {
        sb.AppendLine($"""    <text x="{SvgRenderSupport.F(centerX)}" y="{SvgRenderSupport.F(firstBaselineY)}" text-anchor="middle" font-family="{SvgRenderSupport.Escape(theme.FontFamily)}" font-size="{SvgRenderSupport.F(fontSize)}" fill="{textColor}">{SvgRenderSupport.Escape(lines[0])}</text>""");
        return;
    }

    sb.AppendLine($"""    <text x="{SvgRenderSupport.F(centerX)}" y="{SvgRenderSupport.F(firstBaselineY)}" text-anchor="middle" font-family="{SvgRenderSupport.Escape(theme.FontFamily)}" font-size="{SvgRenderSupport.F(fontSize)}" fill="{textColor}">""");
    sb.AppendLine($"""      <tspan x="{SvgRenderSupport.F(centerX)}" y="{SvgRenderSupport.F(firstBaselineY)}">{SvgRenderSupport.Escape(lines[0])}</tspan>""");

    for (int i = 1; i < lines.Length; i++)
        sb.AppendLine($"""      <tspan x="{SvgRenderSupport.F(centerX)}" dy="{SvgRenderSupport.F(lineHeight)}">{SvgRenderSupport.Escape(lines[i])}</tspan>""");

    sb.AppendLine("    </text>");
}

