private replayEvents() {
    this.events.forEach((event) => {
        this.newSystemEventSubject.next(event);
        this.newUserEventSubject.next(event);
    });
}

public observeNewEventsAsSystem(eventTypes: ExamLiveEventType[] = []): Observable<ExamLiveEvent> {
    const observable = this.newSystemEventSubject.asObservable().pipe(
        filter(
            (event: ExamLiveEvent) =>
                !this.lastAcknowledgedEventStatus?.acknowledgedEvents[String(event.id)]?.system && (eventTypes.length === 0 || eventTypes.includes(event.eventType)),
        ),
        tap((event: ExamLiveEvent) => this.setEventAcknowledgeTimestamps(event)),
        distinct((event) => event.id),
    );
    // Schedule a replay after the current call stack completes (via setTimeout/macrotask)
    // so the caller can subscribe to the returned observable before events start flowing.
    // Without this, events already in memory would not reach a subscriber that was just created.
    setTimeout(() => this.replayEvents());
    return observable;

func lookupPath(doc *yaml.Node, path []string) *yaml.Node {
	n := doc
	if n.Kind == yaml.DocumentNode && len(n.Content) > 0 {
		n = n.Content[0]
	}
	for _, seg := range path {
		if n == nil || n.Kind != yaml.MappingNode {
			return nil
		}
		var found *yaml.Node
		for i := 0; i+1 < len(n.Content); i += 2 {
			if n.Content[i].Value == seg {
				found = n.Content[i+1]
				break
			}
		}
		if found == nil {
			return nil
		}
		n = found
	}
	return n
}

