private convertStyle(
  legend: BivariateLegend | null,
  style: LayerStyle | null,
): MultivariateLayerStyle | null {
  if (style && style.type === 'mcda') {
    return mcdaToMultivariateStyle(style);
  }
  if (legend) {
    return legendToMultivariateStyle(legend);
  }
  return null;
}

export function legendToMultivariateStyle(legend: BivariateLegend): MultivariateLayerStyle {
  const scoreLayers = createMCDALayersFromBivariateAxes([legend.axis.x]);
  const baseLayers = createMCDALayersFromBivariateAxes([legend.axis.y]);
  const scoreStyle: MCDALayerStyle = {
    type: 'mcda',
    config: createDefaultMCDAConfig({
      name: legend.axis.x.label || legend.axis.x.quotient.join('/'),
      layers: scoreLayers,
    }),
  };
  const baseStyle: MCDALayerStyle = {
    type: 'mcda',
    config: createDefaultMCDAConfig({
      name: legend.axis.y.label || legend.axis.y.quotient.join('/'),
      layers: baseLayers,
    }),
  };
  const colors: ColorTheme = legend.steps.map((step) => ({
    id: step.label,
    color: step.color,
    isFallbackColor: step.isFallbackColor,
  }));
  return {
    type: 'multivariate',
    config: {
      version: 0,
      id: legend.name,
      name: legend.name,
      score: scoreStyle,
      base: baseStyle,
      stepOverrides: {
        scoreSteps: legend.axis.x.steps,
        baseSteps: legend.axis.y.steps,
      },
      colors: { type: 'bivariate', colors },
    },
  };
}

export function mcdaToMultivariateStyle(style: MCDALayerStyle): MultivariateLayerStyle {
  return {
    type: 'multivariate',
    config: {
      version: 0,
      id: style.config.id,
      name: style.config.name,
      score: style,
      colors: { type: 'mcda', colors: style.config.colors },
    },
  };

willSourceUpdate({ map, state }: { map: ApplicationMap; state: LogicalLayerState }): void {
  const legend = state.legend as BivariateLegend | null;
  const style = state.style as LayerStyle | null;
  const converted = this.convertStyle(legend, style);
  super.willSourceUpdate({ map, state: { ...state, style: converted } });
}

willMount({ map, state }: { map: ApplicationMap; state: LogicalLayerState }): void {
  const legend = state.legend as BivariateLegend | null;
  const style = state.style as LayerStyle | null;
  const converted = this.convertStyle(legend, style);
  super.willMount({ map, state: { ...state, style: converted } });
}

private static double EstimateTextWidth(Label label, double fontSize) =>
    EstimateTextWidth(string.Join('\n', GetLabelLines(label)), fontSize);

private static double EstimateTextWidth(string? text, double fontSize)
{
    if (string.IsNullOrEmpty(text))
        return 0;

    return text
        .Replace("\r", string.Empty, StringComparison.Ordinal)
        .Split('\n')
        .Max(line => line.Length) * fontSize * AvgGlyphAdvanceEm;
}

private static int GetTextLineCount(Label label) => GetLabelLines(label).Length;

private static double GetTextBlockHeight(Label label, double fontSize)
{
    int lineCount = GetTextLineCount(label);
    if (lineCount == 0)
        return 0;

    return fontSize + (lineCount - 1) * fontSize * DefaultLabelLineHeight;
}

private static string[] GetLabelLines(Label label) =>
